// One-shot check: serve dist/, open it in headless Chrome, putt at the hole until it drops.
// Usage: node scripts/play-check.mjs [path-to-chrome]   (exits when done)
import { createServer } from "node:http";
import { readFile, mkdtemp } from "node:fs/promises";
import { spawn } from "node:child_process";
import { tmpdir } from "node:os";
import { join, extname } from "node:path";

const dist = new URL("../dist/", import.meta.url);
const types = { ".html": "text/html", ".js": "text/javascript", ".css": "text/css", ".woff2": "font/woff2", ".woff": "font/woff" };
const server = createServer(async (req, res) => {
  const path = req.url === "/" ? "index.html" : decodeURIComponent(req.url.slice(1).split("?")[0]);
  try { res.writeHead(200, { "content-type": types[extname(path)] || "application/octet-stream" }).end(await readFile(new URL(path, dist))); }
  catch { res.writeHead(404).end(); }
}).listen(0);
const url = `http://127.0.0.1:${server.address().port}/`;

const chrome = process.argv[2] || "C:/Program Files/Google/Chrome/Application/chrome.exe";
const profile = await mkdtemp(join(tmpdir(), "play-check-"));
const browser = spawn(chrome, ["--headless=new", "--remote-debugging-port=0", `--user-data-dir=${profile}`, "--window-size=1440,900",
  "--enable-unsafe-swiftshader", "--use-angle=swiftshader", "--no-first-run", url]);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const done = (code, msg) => { console.log(msg); browser.kill(); server.close(); process.exit(code); };
setTimeout(() => done(1, "FAIL: timed out"), 90000);

const port = await new Promise((resolve) => {
  let buf = "";
  browser.stderr.on("data", (d) => { buf += d; const m = buf.match(/127\.0\.0\.1:(\d+)\//); if (m) resolve(m[1]); });
});
let page;
for (let n = 0; n < 40 && !page; n++) { await sleep(250); page = (await (await fetch(`http://127.0.0.1:${port}/json/list`)).json()).find((t) => t.type === "page"); }
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((r) => ws.addEventListener("open", r));
let id = 0; const waiting = new Map();
ws.addEventListener("message", (e) => { const m = JSON.parse(e.data); waiting.get(m.id)?.(m.result); waiting.delete(m.id); });
const cdp = (method, params = {}) => new Promise((r) => { waiting.set(++id, r); ws.send(JSON.stringify({ id, method, params })); });
const read = async () => (await cdp("Runtime.evaluate", { expression:
  `JSON.stringify({ pin: document.querySelector('[data-c=pin]').textContent, putts: document.querySelector('[data-c=putts]').textContent, brk: document.querySelector('[data-c=brk]').textContent, toast: document.getElementById('toast').classList.contains('on') ? document.getElementById('toast').textContent : '' })`,
})).result.value;

await sleep(4000); // fonts, first frames
console.log("start", await read());
const HOLE = { x: 720, y: 562 }; // where the cup sits on screen at 1440x900 (from the check screenshots)
for (let putt = 1; putt <= 6; putt++) {
  for (const type of ["mouseMoved", "mousePressed", "mouseReleased"])
    await cdp("Input.dispatchMouseEvent", { type, ...HOLE, button: "left", clickCount: 1, pointerType: "mouse" });
  let s, holed = false;
  for (let n = 0; n < 60; n++) { // wait for the roll to finish (slow software rendering)
    await sleep(250); s = JSON.parse(await read());
    if (s.toast) { holed = true; break; }
    if (n > 4 && s.brk !== "rolling…") break;
  }
  console.log(`putt ${putt}`, JSON.stringify(s));
  if (holed) done(0, `PASS: holed after ${putt} putt(s)`);
  if (!s.putts.startsWith(String(putt))) done(1, "FAIL: putt counter did not go up");
}
done(1, "FAIL: never holed in 6 putts");

